from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import issue_credit_note
from ledgerly.models import Invoice, LineItem
from ledgerly.errors import BillingError
audit.clear()
inv = Invoice('inv_1','cus_1',lines=[LineItem('Seat',1,Decimal('50.00'))],status='issued')
r1 = issue_credit_note(inv, Decimal('10.00'), 'goodwill', idempotency_key='k1')
r2 = issue_credit_note(inv, Decimal('10.00'), 'goodwill', idempotency_key='k1')
print(r1, r2, r1==r2, len(audit.events('credit_note_issued')))
print(audit.events('credit_note_issued'))
for args in [(Decimal('0'),'x'),(Decimal('60'),'x')]:
    try: issue_credit_note(inv,*args)
    except BillingError as e: print(e.code)
inv2 = Invoice('inv_2','c',lines=[LineItem('x',1,Decimal('10'))],status='draft')
try: issue_credit_note(inv2, Decimal('1'),'x')
except BillingError as e: print(e.code)
try: issue_credit_note(inv, Decimal('600'),'x')
except BillingError as e: print(e.code)
print(issue_credit_note(inv, Decimal('600'),'x',approved_by='mgr')['amount'])
""}

